"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[678],{9021(e){e.exports=JSON.parse('{"title":"\uacc4\uc18d \uac1c\ubc1c\uc744 \uc9c0\uc18d\ud558\uae30 \uc704\ud574\uc11c.","date":"2024-12-28","coverUrl":"/kudzu-based-bench/assets/notion/1cc5593d8bcd7ddf.png","html":"<h2 data-notion-block-id=\\"168e548d-8a8e-8085-806e-c3f848c70e6e\\" id=\\"168e548d-8a8e-8085-806e-c3f848c70e6e\\">\uacc4\uc18d \uac1c\ubc1c\uc744 \uc9c0\uc18d\ud558\uae30 \uc704\ud574\uc11c.</h2><a href=\\"https://berthub.eu/articles/posts/on-long-term-software-development/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://berthub.eu/articles/posts/on-long-term-software-development/</a><p data-notion-block-id=\\"168e548d-8a8e-80f8-84cf-ee8c24333b41\\">\uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \uc9c0\uc18d\uc801\uc73c\ub85c \uac1c\ubc1c\ud558\uae30 \uc704\ud574\uc11c \uc758\uc874\uc131\uc744 \ud56d\uc0c1 \uace0\ubbfc\ud558\uace0, \uc885\uc885 \ud574\ub2f9 \uc758\uc874\uc131\uc774 \ub9de\ub294\uc9c0 \uace0\ubbfc\ud574\ubd10\uc57c \ud55c\ub2e4\ub294 \uad8c\uc7a5\ubd80\ud130, \uc5ec\ub7ec\uac00\uc9c0 \uc0dd\uac01\ud574\ubcfc\ub9cc\ud55c \uc694\uc18c\ub97c \uc81c\uc2dc\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uace0\ubbfc\uc744 \ud56d\uc0c1\ud560 \uc218\ub294 \uc5c6\uaca0\uc9c0\ub9cc, \uc8fc\uae30\uc801\uc73c\ub85c \ud574\uc57c\ud558\uace0 \uc774\ub97c \uc704\ud574\uc11c \ud56d\uc0c1 \ubc30\uc6cc\uc57c \ud55c\ub2e4\ub294 \uac83\uc740 \ubcc0\uce58 \uc54a\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"165e548d-8a8e-80d7-9ef7-c5c433ba13dd\\" id=\\"165e548d-8a8e-80d7-9ef7-c5c433ba13dd\\">\ube4c\ub4dc\ud0c0\uc784 \uc18c\uc15c \uc774\ubbf8\uc9c0 \uc0dd\uc131</h2><a href=\\"https://kettanaito.com/blog/build-time-og-images-in-remix\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kettanaito.com/blog/build-time-og-images-in-remix</a><p data-notion-block-id=\\"165e548d-8a8e-8007-9e66-e86c7bd08d4f\\">\ub2e8\uc21c\ud788 OG image\ub97c \ub7f0\ud0c0\uc784 \uc0dd\uc131 \ub300\uc2e0\uc5d0 \ube4c\ub4dc\ud0c0\uc784\uc5d0 \uc0dd\uc131\ud558\ub294 \ubc29\uc548\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc9c0\uc5fd\uc801\uc778 \uc694\uad6c\uc0ac\ud56d\uc5d0\uc11c\ub9cc \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uc544\uc774\ub514\uc5b4\uc9c0\ub9cc, <a href=\\"https://ones-to-watch.ethansup.net/news/post/cd29f440-15b4-4145-a8d4-ec9da1e43ce9#7209e06a-f90c-400f-883b-69e46dbb3b6e\\">Server Component\ub97c \ube4c\ub4dc\ud0c0\uc784\uc5d0 \uc2e4\ud589\ud558\ub294 \ubc29\ubc95</a>\uacfc \uac19\uc774 \ub7f0\ud0c0\uc784\uc5d0 \uc2e4\ud589\ud558\ub358 \uacfc\uc815\uc744 \ube4c\ub4dc\ud0c0\uc784\uc73c\ub85c \uc62e\uae30\ub294 \ubc29\uc2dd\uc740 \uc7a5\ub2e8\uc810\uc744 \uace0\ub824\ud574\uc11c \uc801\uc6a9\ud574\ubcfc\ub9cc \ud558\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"168e548d-8a8e-806b-896d-db7fe5341112\\" id=\\"168e548d-8a8e-806b-896d-db7fe5341112\\">\uae00\uaf34\uc5d0 \uc228\uc5b4\uc788\ub294 \uac83\ub4e4</h2><a href=\\"https://piccalil.li/blog/why-im-excited-about-text-box-trim-as-a-designer/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/why-im-excited-about-text-box-trim-as-a-designer/</a><p data-notion-block-id=\\"168e548d-8a8e-801b-bf52-db83afd52c67\\">\uc8fc \ub0b4\uc6a9\uc740 <code>text-box</code>, <code>text-edge</code>\uc640 \uac19\uc740 \uc2e0 \uae30\ub2a5(\ub274\uc2a4\ub808\ud130 \ubc30\ud3ec \ub2f9\uc2dc draft\uc0c1\ud0dc\uc784)\uc774 \uc88b\uc740 \uc774\uc720\uc774\uc9c0\ub9cc, \uae00\uaf34\uc5d0 \uad00\ub828\ub41c CSS \uc18d\uc131(\uac70\uc758 <code>line-height</code>)\uc5d0 \uc228\uc740 \ud14d\uc2a4\ud2b8 \uc815\ub82c\uc5d0 \ub300\ud55c \uc5b4\ub824\uc6c0\uc744 \uc544\ub294\ub370\uc5d0 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"168e548d-8a8e-8012-8bc0-cc2aa3a7a869\\" id=\\"168e548d-8a8e-8012-8bc0-cc2aa3a7a869\\">\uc774\uc81c React form \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \ud544\uc694\uc5c6\uc744\uc9c0\ub3c4?</h2><a href=\\"https://www.robinwieruch.de/react-form-validation/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.robinwieruch.de/react-form-validation/</a><p data-notion-block-id=\\"168e548d-8a8e-8078-b97b-db690508d260\\">React 19\uc5d0\uc11c\ubd80\ud130 <code>useActionState</code>, <code>useFormStatus</code>\uc640 \uac19\uc740 \ud3fc \uad00\ub828 \ud6c5\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4. \ubb3c\ub860 <a href=\\"https://www.react-hook-form.com/\\">react-hook-form</a>, <a href=\\"https://conform.guide/\\">conform</a>\uac19\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 \uac15\ub825\ud558\uc9c0\ub9cc, \ub2e4\ub978 \uc2dc\uc2a4\ud15c\uacfc \uacb0\ud569\ud558\ub824\uba74, \uae30\ubcf8 \uae30\ub2a5\uc744 \uae30\ubc18\uc73c\ub85c \ud6c5\uc744 \ub9cc\ub4e4\uc5b4\ubcfc \uc218\ub3c4 \uc788\uc744 \uac83 \uac19\ub124\uc694.</p><h2 data-notion-block-id=\\"165e548d-8a8e-800b-b5cb-f4d1b6f20594\\" id=\\"165e548d-8a8e-800b-b5cb-f4d1b6f20594\\">React\uc640 DOM</h2><a href=\\"https://calendar.perfplanet.com/2024/5-tips-to-effectively-optimize-inp-in-react/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://calendar.perfplanet.com/2024/5-tips-to-effectively-optimize-inp-in-react/</a><p data-notion-block-id=\\"165e548d-8a8e-803e-ab14-c338a3ba824c\\">React\uc5d0\uc11c \ud754\ud788 \uace0\ub824\ud560 \ub9cc\ud55c \uc131\ub2a5\uc774 \ub290\ub824\uc9c0\ub294 \ubd80\ubd84, \uadf8\ub9ac\uace0 \uac00\uc7a5 \uc911\uc694\ud55c DOM \ud06c\uae30\uc5d0 \ub300\ud55c \ubd80\ubd84\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc774\ub97c \ud574\uacb0\ud558\ub294 \ubc29\ubc95\uc740 \uae00\uc5d0 \uc4f0\uc5ec\uc9c4 \ubd80\ubd84 \uc678\uc5d0\ub3c4 \uc6d0\uc778\uc5d0 \ub530\ub77c \ub2e4\ub974\uc9c0\ub9cc, \uc131\ub2a5\uc744 \ub290\ub9ac\uac8c \ud558\ub294 \uc6d0\uc778\uc744 \ucc3e\uae30 \uc704\ud574 \uc2dc\uc791\uc810\uc73c\ub85c \ub450\uace0 \uc2dc\uc791\ud574\ub3c4 \uc88b\uc544\ubcf4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"168e548d-8a8e-80ac-aecf-d3015847f611\\" id=\\"168e548d-8a8e-80ac-aecf-d3015847f611\\">i18n \uac80\uc99d\ud558\uae30</h2><a href=\\"https://lingual.dev/blog/how-to-validate-your-react-i18next-application/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://lingual.dev/blog/how-to-validate-your-react-i18next-application/</a><p data-notion-block-id=\\"168e548d-8a8e-80cb-b755-eedea54fd35e\\">\uad6d\uc81c\ud654 \uad00\ub828 \ud30c\uc77c\uc774 \uc720\ud6a8\ud55c\uc9c0 \ud655\uc778\ud558\ub294 \ubc29\ubc95\uc744 \ucd94\uac00\ud574\ubcf4\ub294 \uacfc\uc815\uc744 \uc801\uc740 \uae00\uc785\ub2c8\ub2e4. \uc790\uc2e0\ub4e4\uc758 \ud328\ud0a4\uc9c0\ub97c \ucd94\ucc9c\ud558\ub294 \uae00\uc774\uc9c0\ub9cc, \uc544\uc774\ub514\uc5b4\ub294 \uc5ec\ub7ec \ubc29\uc2dd\uc73c\ub85c \uad6c\ud604\ud574\ubcfc\ub9cc \ud558\ub124\uc694.</p><h2 data-notion-block-id=\\"168e548d-8a8e-8091-bda3-f467a3d84e84\\" id=\\"168e548d-8a8e-8091-bda3-f467a3d84e84\\">\uc131\ub2a5 \ucd5c\uc801\ud654\ub97c \uc5b4\ud544\ud558\uae30</h2><a href=\\"https://gitnation.com/contents/why-your-performance-work-is-not-seen\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gitnation.com/contents/why-your-performance-work-is-not-seen</a><p data-notion-block-id=\\"168e548d-8a8e-8018-98d6-d582e5616f03\\">\ub9ac\ud329\ud1a0\ub9c1\uc774\ub098 \uc131\ub2a5 \ucd5c\uc801\ud654\uac19\uc740 \uc791\uc5c5\uc744 \uc815\ub2f9\ud654\ud558\uae30 \uc704\ud574 \ud560 \uc218 \uc788\ub294 \uc791\uc5c5\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Lighthouse\uc640 CrUX \ub370\uc774\ud130\uc758 \ucc28\uc774\ubd80\ud130 \ubaa8\ub2c8\ud130\ub9c1 \ub370\uc774\ud130\ub97c \uc313\ub294 \ubc29\uc2dd\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \uc18c\uac1c\ud558\ub294 \uae00\uc774\ub2c8 \uc131\ub2a5 \ucd5c\uc801\ud654\uc5d0 \ub4e4\uc5b4\uac00\uae30 \uc804\uc5d0 \ubcf4\uba74 \uc88b\uc740 \ubc1c\ud45c\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c web.dev\uc5d0\uc11c \uc62c\ub9b0 <a href=\\"https://web.dev/articles/site-speed-and-business-metrics\\">\uc6f9 \uc131\ub2a5\uc744 \uc0ac\uc5c5 \uc9c0\ud45c\uc5d0 \uc5f0\uad00\uc9d3\uae30</a>\ub098 <a href=\\"https://web.dev/articles/optimize-cwv-business\\">Core Web Vitals \uc27d\uac8c \uc774\ud574\ud558\uae30</a>\ub3c4 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"168e548d-8a8e-80d4-b538-dae37ec62745\\" id=\\"168e548d-8a8e-80d4-b538-dae37ec62745\\">TypeScript \ub354 \uc798 \uc4f0\uae30</h2><a href=\\"https://gitnation.com/contents/dive-into-advanced-typescript\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gitnation.com/contents/dive-into-advanced-typescript</a><p data-notion-block-id=\\"168e548d-8a8e-808d-bce2-f96ac3a37dc6\\">TypeScript\ub97c \ub354 \uc798 \uc4f0\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \ubc1c\ud45c\uc785\ub2c8\ub2e4. \uc54c \uc218\ub3c4 \uc788\ub294 Type Guard\ubd80\ud130 \ub7f0\ud0c0\uc784 \ud0c0\uc785 \uac80\uc99d, <code>never</code>\ud0c0\uc785\uc744 \uae30\ubcf8 \uac12\uc5d0 \ub123\uae30, <code>assert</code>... \uc5ec\ub7ec\uac00\uc9c0 TypeScript\ub97c \ub354 \uc798 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uae30\uc220\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ubaa8\ub450 \uc801\uc6a9\ud574\ubcf4\ub294 \uac74 \uc5b4\ub835\uaca0\uc9c0\ub9cc, \uc54c\uc544\ub450\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"168e548d-8a8e-80b1-a804-e70f2c8b0b79\\" id=\\"168e548d-8a8e-80b1-a804-e70f2c8b0b79\\">\ubaa8\ub97c \uc218\ub3c4 \uc788\ub294 \ucd5c\uc2e0 API\ub4e4</h2><a href=\\"https://gitnation.com/contents/install-nothing-app-uis-with-native-browser-apis\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gitnation.com/contents/install-nothing-app-uis-with-native-browser-apis</a><p data-notion-block-id=\\"168e548d-8a8e-801f-a44d-f594dfd0ae23\\">\ucd5c\uadfc baseline\uc5d0\uc11c \uc9c0\uc6d0\ud558\uac8c \ub41c \uc5ec\ub7ec \uc560\ub2c8\uba54\uc774\uc158 \uad00\ub828 \ube0c\ub77c\uc6b0\uc800 API, HTML \uc694\uc18c, CSS \uc18d\uc131\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \ubc1c\ud45c\uc785\ub2c8\ub2e4. \uc544\uc9c1 \uad6c\uc2dd \ube0c\ub77c\uc6b0\uc800\uc5d0 100% \uc9c0\uc6d0\uc744 \ud574\uc57c\ud55c\ub2e4\uba74 \uc4f0\uae30 \uc5b4\ub835\uaca0\uc9c0\ub9cc, \uc544\ub2c8\ub77c\uba74 \uc0ac\uc6a9\ud574\ubcfc\ub9cc\ud569\ub2c8\ub2e4.</p>"}')}}]);